begin;
do $$declare a uuid:=gen_random_uuid();t uuid:=gen_random_uuid();s uuid:=gen_random_uuid();s2 uuid:=gen_random_uuid();par uuid:=gen_random_uuid();ase uuid:=gen_random_uuid();tse uuid:=gen_random_uuid();sse uuid:=gen_random_uuid();s2se uuid:=gen_random_uuid();pse uuid:=gen_random_uuid();uid uuid;sid uuid;rol text;task text;yr uuid;c uuid;c2 uuid;family uuid;sub uuid;ny uuid;nc uuid;account uuid;slip uuid;book uuid;asset uuid;ats uuid;request uuid;v bigint;r jsonb;cmd jsonb;frozen jsonb;kind text;sem integer:=case when extract(month from public.app_ops_today())>=7 then 1 else 2 end;sy integer:=extract(year from public.app_ops_today())::integer-case when extract(month from public.app_ops_today())<7 then 1 else 0 end;checks integer:=0;
begin
 for uid,sid,rol in select * from(values(a,ase,'admin'),(t,tse,'teacher'),(s,sse,'student'),(s2,s2se,'student'),(par,pse,'parent'))x loop
 insert into auth.users(id,aud,role,email) values(uid,'authenticated','authenticated','stage25-'||uid||'@example.invalid');insert into auth.sessions(id,user_id) values(sid,uid);
 insert into public.profiles(id,username,full_name,contact_email) values(uid,'v'||replace(uid::text,'-',''),'Validation Stage 25','stage25-'||uid||'@example.invalid');
 insert into public.user_roles(user_id,role_code) values(uid,rol);insert into sim_murid_private.auth_accounts(user_id,must_change_password,profile_completed_at,verified_contact_email) values(uid,false,now(),'stage25-'||uid||'@example.invalid');insert into sim_murid_private.security_questions(user_id,question_code,answer_hash) values(uid,'q1',repeat('0',64));if rol='teacher' then insert into public.user_access_flags(user_id,teacher_email_verified_at) values(uid,now());end if;perform public.app_auth_claim(uid,sid,false);end loop;
 foreach task in array array['duty_teacher','student_mentor','committee_treasurer','savings_manager'] loop insert into public.user_assignments(user_id,assignment_code,valid_from,assigned_by) values(t,task,public.app_ops_today()-1,a);end loop;
 select id into yr from public.academic_years where start_year=sy;if yr is null then insert into public.academic_years(start_year) values(sy) returning id into yr;end if;
 insert into public.classes(academic_year_id,name,level,homeroom_teacher_id) values(yr,'VALID-25-7-'||left(a::text,8),7,t) returning id into c;insert into public.classes(academic_year_id,name,level) values(yr,'VALID-25-9-'||left(a::text,8),9) returning id into c2;
 insert into sim_murid_private.enrollments(student_id,class_id,academic_year_id,starts_on,created_by) values(s,c,yr,make_date(sy,7,1),a),(s2,c2,yr,make_date(sy,7,1),a);
 insert into sim_murid_private.student_guardians(student_id,parent_id,relationship,verified_by) values(s,par,'father',a);
 insert into sim_murid_private.family_groups(name,created_by) values('Validation siblings',a) returning id into family;insert into sim_murid_private.family_members(family_id,student_id,created_by) values(family,s,a),(family,s2,a);

 select id into sub from public.subjects order by sort_order limit 1;
 insert into sim_murid_private.lesson_schedules(class_id,academic_year_id,subject_id,teacher_id,weekday,start_minute,duration_minutes,jtm,created_by) values(c,yr,sub,t,1,480,40,1,a);
 select id into ny from public.academic_years where start_year=sy+1;if ny is null then insert into public.academic_years(start_year) values(sy+1) returning id into ny;end if;
 insert into public.classes(academic_year_id,name,level) values(ny,'VALID-25-8-'||left(a::text,8),8) returning id into nc;
 execute 'set local role service_role';
 update sim_murid_private.fee_brackets set active=false;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(a,ase,gen_random_uuid(),v,'savings',jsonb_build_object('type','bracket','id',null,'minimum',1000,'maximum',null,'percent',1,'active',true));if r->>'code'<>'saved' then raise exception 'Fee bracket %',r;end if;checks=checks+1;
 r=public.app_fee_quote(t,tse,123000,true);if (r->>'fee')::int<>1000 or(r->>'cash')::int<>122000 then raise exception 'Fee rounding %',r;end if;checks=checks+1;
 if (public.app_fee_quote(t,tse,150000,true)->>'fee')::int<>2000 then raise exception 'Half up rounding';end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(t,tse,gen_random_uuid(),v,'savings',jsonb_build_object('type','account','ownerId',s,'category','S'));account=(r->>'id')::uuid;if account is null then raise exception 'Account %',r;end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(t,tse,gen_random_uuid(),v,'savings',jsonb_build_object('type','transaction','id',null,'accountId',account,'date',public.app_ops_today(),'kind','deposit','amount',200000,'reason','Validation deposit'));if r->>'code'<>'saved' then raise exception 'Deposit %',r;end if;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(t,tse,gen_random_uuid(),v,'savings',jsonb_build_object('type','transaction','id',null,'accountId',account,'date',public.app_ops_today(),'kind','withdrawal','amount',123000,'feeApplied',true,'reason','Validation withdraw'));if r->>'code'<>'saved' then raise exception 'Withdraw %',r;end if;select id into slip from sim_murid_private.withdrawal_slips where transaction_id=(r->>'id')::uuid;if slip is null then raise exception 'Slip absent';end if;checks=checks+1;
 if(public.app_operations_read(s,sse,'savings')#>>'{summary,balance}')::bigint<>77000 then raise exception 'Gross debit mismatch';end if;checks=checks+1;
 if(public.app_slip_read(s,sse,slip)#>>'{snapshot,fee,cash}')::bigint<>122000 or public.app_slip_read(s2,s2se,slip) is not null then raise exception 'Slip scope or cash';end if;checks=checks+1;
 r=public.app_slip_delivery(a,ase,slip,'queue');if r->>'code'<>'queued' then raise exception 'Delivery queue %',r;end if;v=(r->>'count')::int;r=public.app_slip_delivery(a,ase,slip,'queue');if(r->>'count')::int<>v then raise exception 'Delivery duplicate';end if;checks=checks+1;
 foreach kind in array array['PH','ATS','ASAS','Praktik'] loop
 select revision into v from sim_murid_private.operations_state;cmd=jsonb_build_object('type','batch','id',null,'classId',c,'subjectId',sub,'date',public.app_ops_today(),'kind',kind,'items',jsonb_build_array(jsonb_build_object('studentId',s,'value',case kind when 'PH' then 80 when 'ATS' then 70 when 'ASAS' then 90 else 0 end)));
 r=public.app_learning_write(t,tse,gen_random_uuid(),v,'grades',cmd);if r->>'code'<>'saved' then raise exception 'Grade % %',kind,r;end if;checks=checks+1;if kind='ATS' then ats=(r->>'id')::uuid;end if;
 end loop;
 r=public.app_report_draft(s,sse,s,c,sem);if(r#>>'{subjects,0,final}')::numeric<>82 or(r#>>'{subjects,0,practice}')::numeric<>0 then raise exception 'Report formula %',r;end if;checks=checks+1;
 if public.app_report_draft(t,gen_random_uuid(),s,c,sem) is not null then raise exception 'Revoked report scope';end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_learning_write(t,tse,gen_random_uuid(),v,'reports',jsonb_build_object('type','publish','classId',c,'semester',sem,'studentIds',jsonb_build_array(s)));if r->>'code'<>'saved' then raise exception 'Publish %',r;end if;checks=checks+1;
 select snapshot into frozen from sim_murid_private.report_snapshots where student_id=s;
 select revision into v from sim_murid_private.operations_state;cmd=jsonb_build_object('type','batch','id',ats,'classId',c,'subjectId',sub,'date',public.app_ops_today(),'kind','ATS','items',jsonb_build_array(jsonb_build_object('studentId',s,'value',0)),'reason','Validation correction');request=gen_random_uuid();r=public.app_learning_write(t,tse,request,v,'grades',cmd);if r->>'code'<>'saved' then raise exception 'Grade correction %',r;end if;if (select snapshot from sim_murid_private.report_snapshots where student_id=s) is distinct from frozen then raise exception 'Published changed';end if;checks=checks+1;
 if public.app_learning_write(t,tse,request,v,'grades',cmd) is distinct from r then raise exception 'Replay mismatch';end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;cmd=jsonb_build_object('type','revise','classId',c,'semester',sem,'studentId',s,'expectedVersion',1,'reason','D10 validation correction');request=gen_random_uuid();r=public.app_learning_write(t,tse,request,v,'reports',cmd);if r->>'code'<>'saved' or (r->>'version')::integer<>2 then raise exception 'Report revision %',r;end if;checks=checks+1;
 if public.app_learning_write(t,tse,request,v,'reports',cmd) is distinct from r then raise exception 'Revision replay mismatch';end if;checks=checks+1;
 if (select snapshot from sim_murid_private.report_snapshots where student_id=s) is distinct from frozen then raise exception 'D10 changed base archive';end if;checks=checks+1;
 r=public.app_learning_read(a,ase,'reports',jsonb_build_object('classId',c,'semester',sem,'reportVersion',1));if r#>'{rows,0,published,snapshot}' is distinct from frozen then raise exception 'Historical read mismatch';end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_learning_write(a,ase,gen_random_uuid(),v,'promotions',jsonb_build_object('type','promote','sourceYearId',yr,'targetYearId',ny,'items',jsonb_build_array(jsonb_build_object('studentId',s,'classId',nc,'expectedClassId',c),jsonb_build_object('studentId',s2,'classId',null,'expectedClassId',c2)),'reason','Validation annual promotion'));if r->>'code'<>'saved' then raise exception 'Promotion %',r;end if;checks=checks+1;
 if (select role_code from public.user_roles where user_id=s2)<>'alumni' or (select count(*) from sim_murid_private.promotion_history where student_id in(s,s2))<>2 then raise exception 'Promotion history';end if;checks=checks+1;
 if public.app_diploma_allowed(s2,s2se,s2) then raise exception 'Diploma default allow';end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_learning_write(a,ase,gen_random_uuid(),v,'promotions',jsonb_build_object('type','access','scope','individual','studentIds',jsonb_build_array(s2),'view','allow','download','deny'));if not public.app_diploma_allowed(s2,s2se,s2) or public.app_diploma_allowed(s2,s2se,s2,true) then raise exception 'Diploma overrides';end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_learning_write(a,ase,gen_random_uuid(),v,'books',jsonb_build_object('type','book','title','VALID-25-premium','premium',true));book=(r->>'id')::uuid;if book is null then raise exception 'Book %',r;end if;checks=checks+1;
 if public.app_book_allowed(s,sse,book) then raise exception 'Premium access leaked';end if;checks=checks+1;
 asset=gen_random_uuid();r=public.app_asset_write(a,ase,'prepare',jsonb_build_object('id',asset,'kind','book','targetId',book,'mime','application/pdf','size',100,'filename','validation.pdf'));if r->>'code'<>'saved' then raise exception 'Asset prepare %',r;end if;
 if public.app_asset_get(a,ase,asset) is not null then raise exception 'Pending asset readable';end if;checks=checks+1;
 r=public.app_asset_write(a,ase,'ready',jsonb_build_object('id',asset,'sha256',repeat('a',64)));if r->>'code'<>'saved' or public.app_asset_get(s,sse,asset) is not null then raise exception 'Asset scope %',r;end if;checks=checks+1;
 if has_function_privilege('authenticated','public.app_learning_write(uuid,uuid,uuid,bigint,text,jsonb)','execute') then raise exception 'Direct RPC';end if;checks=checks+1;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','sim_murid_private') and c.relkind='r' and not c.relrowsecurity) then raise exception 'RLS absent';end if;checks=checks+1;
 perform set_config('app.stage25.verification',jsonb_build_object('status','passed','assertions',checks,'mode','cloud service_role transaction rolled back','email_sent',false,'storage_uploaded',false)::text,true);
end$$;
select current_setting('app.stage25.verification')::jsonb verification;
rollback;
